<script setup lang="ts">
import { computed, reactive, ref, onMounted } from 'vue'
import { useRoute } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { api, newKey, headers } from '../api/client'
import { money, downloadCodes } from '../utils/format'
import RecordTable from '../components/RecordTable.vue'
const route=useRoute(), section=computed(()=>String(route.params.section))
const titles:Record<string,string>={dashboard:'数据概览',users:'用户管理',products:'商品套餐',codes:'卡密管理',orders:'订单管理',wallets:'钱包管理',agents:'代理管理',settings:'系统设置','audit-logs':'操作日志'}
const loading=ref(false),busy=ref(false),rows=ref<any[]>([]),page=ref(1),total=ref(0),q=ref(section.value==='orders'&&typeof route.query.q==='string'?route.query.q.slice(0,100):''),status=ref(''),dashboard=ref<any>({}),productOptions=ref<any[]>([]),selected=ref<number[]>([])
const productFilter=ref<number>(),dateRange=ref<[string,string]>()
const settings=reactive({sales_enabled:true,redemption_enabled:true})
const dialog=ref(''), editingId=ref<number|null>(null),generated=ref<string[]>([]),batch=ref(''),events=ref<any[]>([]),transactions=ref<any[]>([])
const productVersion=ref('')
const product=reactive({name:'',description:'',category:'数字服务',original_price:19900,price:14900,agent_price:11900,stock:100,active:true,sort:0})
const code=reactive<{product_id:number|undefined;quantity:number;valid_days:number;owner_id:number|null}>({product_id:undefined,quantity:10,valid_days:30,owner_id:null})
const userEdit=reactive({active:true,role:'user'}),adjust=reactive({amount:10000,note:'',operation:'adjust'}),adjustKey=ref(newKey())
const eventColumns=[{key:'action',label:'操作'},{key:'note',label:'说明',width:220},{key:'created_at',label:'时间',type:'date',width:180}]
const ledgerColumns=[{key:'kind',label:'类型',type:'status'},{key:'amount',label:'余额变动',type:'money'},{key:'frozen_delta',label:'冻结变动',type:'money'},{key:'balance_after',label:'余额',type:'money'},{key:'note',label:'备注'},{key:'created_at',label:'时间',type:'date',width:180}]
const columns=computed(()=>{
 switch(section.value){
 case 'users':case 'agents':return[{key:'id',label:'ID',width:70},{key:'email',label:'邮箱',width:200},{key:'name',label:'昵称'},{key:'role',label:'角色',type:'status'},{key:'active',label:'账号状态',type:'boolean'},{key:'created_at',label:'注册时间',type:'date',width:180}]
 case 'products':return[{key:'id',label:'ID',width:60},{key:'name',label:'商品名称',width:210},{key:'price',label:'零售价',type:'money'},{key:'agent_price',label:'代理价',type:'money'},{key:'stock',label:'可售库存'},{key:'active',label:'上架状态',type:'boolean'}]
 case 'codes':return[{key:'id',label:'编号'},{key:'suffix',label:'卡密尾号'},{key:'product_id',label:'商品ID'},{key:'owner_id',label:'代理ID'},{key:'status',label:'状态',type:'status'},{key:'expires_at',label:'到期时间',type:'date',width:180}]
 case 'orders':return[{key:'id',label:'订单编号',width:220},{key:'user_id',label:'用户ID',width:80},{key:'product_name',label:'商品',width:160},{key:'amount',label:'金额',type:'money'},{key:'payment_status',label:'支付状态',type:'status'},{key:'fulfillment_status',label:'履约状态',type:'status'},{key:'created_at',label:'时间',type:'date',width:180}]
 case 'wallets':return[{key:'user_id',label:'用户ID'},{key:'balance',label:'可用余额',type:'money'},{key:'frozen',label:'冻结余额',type:'money'},{key:'updated_at',label:'更新时间',type:'date',width:180}]
 default:return[{key:'actor_id',label:'管理员ID'},{key:'action',label:'操作',width:180},{key:'target',label:'目标',width:200},{key:'detail',label:'详情',width:220},{key:'created_at',label:'时间',type:'date',width:180}]
 }
})
async function load(){loading.value=true;try{
 if(section.value==='dashboard'){dashboard.value=(await api.get('/admin/dashboard')).data;return}
 if(section.value==='settings'){Object.assign(settings,(await api.get('/admin/settings')).data);return}
 const endpoint=section.value==='agents'?'users':section.value
 const{data}=await api.get(`/admin/${endpoint}`,{params:{page:page.value,q:q.value,status:status.value,role:section.value==='agents'?'agent':undefined,product_id:productFilter.value,start:dateRange.value?.[0],end:dateRange.value?.[1]}})
 rows.value=data.items;total.value=data.total
 }finally{loading.value=false}}
function openProduct(row?:any){editingId.value=row?.id||null;productVersion.value=row?.updated_at||'';Object.assign(product,row?{name:row.name,description:row.description,category:row.category,original_price:row.original_price,price:row.price,agent_price:row.agent_price??row.price,stock:row.stock,active:row.active,sort:row.sort}:{name:'',description:'',category:'数字服务',original_price:19900,price:14900,agent_price:11900,stock:100,active:true,sort:0});dialog.value='product'}
async function saveProduct(){busy.value=true;try{await(editingId.value?api.put(`/admin/products/${editingId.value}`,{...product,expected_updated_at:productVersion.value}):api.post('/admin/products',product));dialog.value='';ElMessage.success('商品已保存');await load()}finally{busy.value=false}}
async function openGenerate(){productOptions.value=(await api.get('/admin/products',{params:{page_size:100}})).data.items;generated.value=[];dialog.value='generate'}
async function generate(){busy.value=true;try{const{data}=await api.post('/admin/codes/generate',code);generated.value=data.codes;batch.value=data.batch_id;await load()}finally{busy.value=false}}
async function closeGenerate(done:()=>void){if(generated.value.length){try{await ElMessageBox.confirm('完整卡密只展示一次，确认已下载并安全保存？','关闭前确认');generated.value=[];done()}catch{}}else done()}
async function voidCodes(ids:number[]){try{await ElMessageBox.confirm(`确认作废 ${ids.length} 张未使用卡密？此操作不能撤销。`,'作废卡密',{type:'warning'})}catch{return}await api.post('/admin/codes/void',{ids});ElMessage.success('卡密已作废');await load()}
function openUser(row:any){editingId.value=row.id;userEdit.active=row.active;userEdit.role=row.role;dialog.value='user'}
async function saveUser(){busy.value=true;try{await api.patch(`/admin/users/${editingId.value}`,userEdit);dialog.value='';await load();ElMessage.success('账号权限已更新，原登录会话已失效')}finally{busy.value=false}}
function openAdjust(row:any){editingId.value=row.user_id;Object.assign(adjust,{amount:10000,note:'',operation:'adjust'});adjustKey.value=newKey();dialog.value='adjust'}
async function saveAdjust(){busy.value=true;try{await api.post(`/admin/wallets/${editingId.value}/adjust`,adjust,headers(adjustKey.value));dialog.value='';await load();ElMessage.success('钱包操作已记账')}finally{busy.value=false}}
async function orderAction(row:any,action:string){let note:string;try{const result=await ElMessageBox.prompt('请填写操作原因，所有变更会记录审计日志。','确认订单操作',{inputValidator:v=>(v?.trim().length>=3)||'请填写至少3个字符',type:'warning'});note=result.value}catch{return}await api.post(`/admin/orders/${row.id}/action`,{action,note});ElMessage.success('订单已更新');await load()}
async function showEvents(id:string){events.value=(await api.get(`/admin/orders/${id}/events`)).data;dialog.value='events'}
async function showLedger(id:number){transactions.value=(await api.get(`/admin/wallets/${id}/transactions`,{params:{page_size:100}})).data.items;dialog.value='ledger'}
async function saveSettings(){busy.value=true;try{await api.put('/admin/settings',settings);ElMessage.success('业务开关已保存')}finally{busy.value=false}}
onMounted(async()=>{await load();if(section.value==='orders')productOptions.value=(await api.get('/admin/products',{params:{page_size:100}})).data.items})
</script>
<template><div class="section-heading"><div><p class="eyebrow">YUNGUO / ADMINISTRATION</p><h1>{{titles[section]||'管理工作台'}}</h1><p class="muted">{{section==='dashboard'?'掌握业务全貌，让每一笔交付有迹可循。':'统一管理业务数据，关键操作自动记录审计。'}}</p></div><div class="toolbar"><el-button @click="load" :loading="loading">刷新数据</el-button><el-button v-if="section==='products'" type="primary" @click="openProduct()">＋ 新建商品</el-button><el-button v-if="section==='codes'" type="primary" @click="openGenerate">＋ 批量生成卡密</el-button></div></div>
<template v-if="section==='dashboard'"><div class="stats-grid" v-loading="loading"><div class="stat-card"><span>累计净交易额</span><strong>{{money(dashboard.revenue)}}</strong><small>已支付的钱包订单 · 含演示资金</small></div><div class="stat-card"><span>订单总数</span><strong>{{dashboard.orders||0}}<em>笔</em></strong><small>待履约 {{dashboard.statuses?.QUEUED||0}} 笔</small></div><div class="stat-card"><span>注册用户</span><strong>{{dashboard.users||0}}<em>人</em></strong><small>覆盖普通用户、代理与管理员</small></div><div class="stat-card"><span>有效卡密库存</span><strong>{{dashboard.available_codes||0}}<em>张</em></strong><small>未使用且在有效期内</small></div></div><div class="dashboard-grid"><section class="panel"><div class="section-heading compact"><h3>交易趋势</h3><span class="muted">最近 14 个交易日</span></div><div v-if="dashboard.trend?.length" class="bar-chart"><div v-for="day in dashboard.trend" :key="day.date" class="bar-column"><small>{{money(day.amount)}}</small><div :style="{height:Math.max(5,day.amount/Math.max(...dashboard.trend.map((d:any)=>d.amount),1)*140)+'px'}"></div><span>{{day.date.slice(5)}}</span></div></div><el-empty v-else description="完成第一笔交易后查看趋势" :image-size="70" /></section><section class="panel"><p class="eyebrow">OPERATIONS</p><h3>今天，从这里开始。</h3><p class="muted">及时处理待履约订单，核对资金流水，关注异常状态。</p><router-link to="/admin/orders" class="shortcut">处理订单 <span>↗</span></router-link><router-link to="/admin/codes" class="shortcut">管理卡密 <span>↗</span></router-link></section></div><section class="panel table-panel"><div class="section-heading compact"><h3>最近订单</h3><router-link to="/admin/orders">全部订单 →</router-link></div><RecordTable :rows="dashboard.recent_orders||[]" :columns="[{key:'id',label:'订单编号',width:230},{key:'product_name',label:'商品',width:180},{key:'amount',label:'金额',type:'money'},{key:'fulfillment_status',label:'履约状态',type:'status'},{key:'created_at',label:'时间',type:'date',width:180}]" /></section></template>
<section v-else-if="section==='settings'" class="panel form-panel"><h3>业务开关</h3><p class="muted">关闭后，新的购买或兑换将被后端拒绝，已创建订单可继续处理。</p><form @submit.prevent="saveSettings"><label class="switch-label">商品销售 <el-switch v-model="settings.sales_enabled" /></label><label class="switch-label">卡密兑换 <el-switch v-model="settings.redemption_enabled" /></label><el-button type="primary" native-type="submit" :loading="busy">保存设置</el-button></form><el-alert class="spaced" title="支付模式、JWT 密钥和履约模式由服务器环境变量配置，不在网页中暴露。" :closable="false" /></section>
<section v-else class="panel table-panel"><div class="toolbar spaced"><el-input v-if="['users','agents','orders'].includes(section)" v-model="q" :placeholder="section==='orders'?'搜索订单编号':'搜索邮箱'" clearable style="width:220px" @keyup.enter="page=1;load()" /><el-select v-if="['orders','codes'].includes(section)" v-model="status" placeholder="全部状态" clearable style="width:160px" @change="page=1;load()"><el-option v-for="(label,value) in section==='codes'?{UNUSED:'未使用',USED:'已使用',VOID:'已作废',EXPIRED:'已过期'}:{QUEUED:'待履约',PROCESSING:'处理中',COMPLETED:'已完成',FAILED:'失败',CANCELED:'已取消'}" :key="value" :value="value" :label="label" /></el-select><template v-if="section==='orders'"><el-select v-model="productFilter" placeholder="全部商品" clearable style="width:180px"><el-option v-for="p in productOptions" :key="p.id" :value="p.id" :label="p.name" /></el-select><el-date-picker v-model="dateRange" type="datetimerange" value-format="YYYY-MM-DDTHH:mm:ssZ" start-placeholder="开始时间" end-placeholder="结束时间" style="max-width:370px" /></template><el-button v-if="['users','agents','orders'].includes(section)" @click="page=1;load()">查询</el-button><el-button v-if="section==='codes'" type="danger" plain :disabled="!selected.length" @click="voidCodes(selected)">作废选中</el-button></div>
<el-table v-if="section==='codes'" :data="rows" v-loading="loading" @selection-change="(items:any[])=>selected=items.map(i=>i.id)" empty-text="暂无卡密"><el-table-column type="selection" width="45" /><el-table-column prop="id" label="编号" width="80"/><el-table-column prop="suffix" label="尾号"/><el-table-column prop="product_id" label="商品ID"/><el-table-column prop="owner_id" label="代理ID"/><el-table-column label="状态"><template #default="{row}">{{row.status==='UNUSED'&&new Date(row.expires_at)<new Date()?'已过期':({UNUSED:'未使用',USED:'已使用',VOID:'已作废'} as Record<string,string>)[row.status]}}</template></el-table-column><el-table-column prop="expires_at" label="到期时间" min-width="200"/><el-table-column label="操作"><template #default="{row}"><el-button link type="danger" :disabled="row.status!=='UNUSED'" @click="voidCodes([row.id])">作废</el-button></template></el-table-column></el-table>
<RecordTable v-else :rows="rows" :columns="columns" :loading="loading"><el-table-column v-if="section!=='audit-logs'" label="操作" :min-width="section==='orders'?290:160" fixed="right"><template #default="{row}"><el-button v-if="['users','agents'].includes(section)" link type="primary" @click="openUser(row)">编辑权限</el-button><el-button v-if="section==='products'" link type="primary" @click="openProduct(row)">编辑套餐</el-button><template v-if="section==='wallets'"><el-button link type="primary" @click="openAdjust(row)">资金操作</el-button><el-button link @click="showLedger(row.user_id)">流水</el-button></template><template v-if="section==='orders'"><el-button link @click="showEvents(row.id)">日志</el-button><template v-if="row.payment_status==='PAID'"><el-button v-if="['QUEUED','PROCESSING'].includes(row.fulfillment_status)" link type="success" @click="orderAction(row,'complete')">完成</el-button><el-button v-if="['QUEUED','PROCESSING'].includes(row.fulfillment_status)" link type="danger" @click="orderAction(row,'fail')">失败</el-button><el-button v-if="row.fulfillment_status==='QUEUED'" link @click="orderAction(row,'cancel')">取消</el-button><el-button v-if="row.fulfillment_status==='FAILED'" link type="primary" @click="orderAction(row,'retry')">重试</el-button><el-button v-if="row.source==='wallet'&&['FAILED','CANCELED'].includes(row.fulfillment_status)" link type="warning" @click="orderAction(row,'refund')">退款</el-button></template></template></template></el-table-column></RecordTable><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="total,prev,pager,next" @current-change="load" /></section>
<el-dialog :model-value="dialog==='product'" @close="dialog=''" :title="editingId?'编辑商品':'新建商品'" width="min(94vw,600px)"><form @submit.prevent="saveProduct"><label>商品名称<input v-model="product.name" required maxlength="120" /></label><label>描述<textarea v-model="product.description" rows="3" maxlength="5000" /></label><div class="form-grid"><label>分类<input v-model="product.category" required /></label><label>可售库存<el-input-number v-model="product.stock" :min="0" :max="1000000" :precision="0" /></label><label>原价（分）<el-input-number v-model="product.original_price" :min="0" :max="100000000" :precision="0" /></label><label>零售价（分）<el-input-number v-model="product.price" :min="0" :max="100000000" :precision="0" /></label><label>代理价（分）<el-input-number v-model="product.agent_price" :min="0" :max="100000000" :precision="0" /></label><label>排序<el-input-number v-model="product.sort" :precision="0" /></label></div><label class="switch-label">上架销售<el-switch v-model="product.active" /></label><el-button type="primary" native-type="submit" :loading="busy">保存套餐</el-button></form></el-dialog>
<el-dialog :model-value="dialog==='generate'" @close="dialog=''" :before-close="closeGenerate" :close-on-click-modal="false" :close-on-press-escape="false" title="批量生成卡密" width="min(94vw,650px)"><template v-if="generated.length"><el-alert title="完整卡密仅展示一次，请立即下载。后台无法再次导出原始卡密。" type="warning" :closable="false" /><pre class="code-preview">{{generated.join('\n')}}</pre><el-button type="primary" @click="downloadCodes(generated,batch)">导出 TXT</el-button><el-button @click="downloadCodes(generated,batch,true)">导出 CSV</el-button></template><form v-else @submit.prevent="generate"><label>商品<el-select v-model="code.product_id" placeholder="选择套餐"><el-option v-for="p in productOptions.filter(p=>p.active)" :key="p.id" :value="p.id" :label="`${p.name}（可售${p.stock}）`" /></el-select></label><label>数量<el-input-number v-model="code.quantity" :min="1" :max="500" :precision="0" /></label><label>有效天数<el-input-number v-model="code.valid_days" :min="1" :max="365" :precision="0" /></label><label>分配代理 ID（可选，清空则平台持有）<el-input-number v-model="code.owner_id" :min="1" :precision="0" /></label><el-button type="primary" native-type="submit" :disabled="!code.product_id" :loading="busy">生成并预留库存</el-button></form></el-dialog>
<el-dialog :model-value="dialog==='user'" @close="dialog=''" title="编辑账号权限" width="min(94vw,420px)"><form @submit.prevent="saveUser"><label>角色<el-select v-model="userEdit.role"><el-option label="普通用户" value="user"/><el-option label="代理商" value="agent"/><el-option label="管理员" value="admin"/></el-select></label><label class="switch-label">账号启用<el-switch v-model="userEdit.active" /></label><el-button type="primary" native-type="submit" :loading="busy">确认修改</el-button></form></el-dialog>
<el-dialog :model-value="dialog==='adjust'" @close="dialog=''" title="钱包资金操作" width="min(94vw,500px)"><form @submit.prevent="saveAdjust"><label>操作<el-select v-model="adjust.operation"><el-option label="调整可用余额（正数增加，负数扣减）" value="adjust"/><el-option label="冻结余额" value="freeze"/><el-option label="解冻余额" value="unfreeze"/></el-select></label><label>金额（分）<el-input-number v-model="adjust.amount" :min="-100000000" :max="100000000" :precision="0" /></label><label>操作原因<input v-model="adjust.note" required minlength="3" maxlength="200" /></label><el-alert class="spaced" title="每笔操作将记录资金流水与管理员审计。" :closable="false" /><el-button type="primary" native-type="submit" :loading="busy">确认记账</el-button></form></el-dialog>
<el-dialog :model-value="dialog==='events'" @close="dialog=''" title="订单处理记录" width="min(94vw,800px)"><RecordTable :rows="events" :columns="eventColumns" /></el-dialog><el-dialog :model-value="dialog==='ledger'" @close="dialog=''" title="最近100笔资金流水" width="min(94vw,1000px)"><RecordTable :rows="transactions" :columns="ledgerColumns" /></el-dialog>
</template>
